public class LoongsonAnalyzer : ConstantPropagationAnalyzer {
	
	private Register linkRegister;

	private static string PROCESSOR_NAME = "Loongarch";

	public LoongsonAnalyzer() : base(PROCESSOR_NAME)
    {
	}

	/* @Override */
	public bool canAnalyze(Program program) {
		bool canAnalyze = program.getLanguage()
				.getProcessor()
				.equals(Processor.findOrPossiblyCreateProcessor(PROCESSOR_NAME));

		if (!canAnalyze) {
			return false;
		}
		
		linkRegister = program.getProgramContext().getRegister("ra");

		return true;
	}

	/* @Override */
	public AddressSet flowConstants(Program program, Address flowStart,
			AddressSetView flowSet, SymbolicPropogator symEval, TaskMonitor monitor)
    {

		// follow all flows building up context
		// use context to fill out addresses on certain instructions
		ConstantPropagationContextEvaluator eval =
			new _Anon_ConstantPropagationContextEvaluator_1(monitor, trustWriteMemOption);

		eval.setTrustWritableMemory(trustWriteMemOption)
				.setMinSpeculativeOffset(minSpeculativeRefAddress)
				.setMaxSpeculativeOffset(maxSpeculativeRefAddress)
				.setMinStoreLoadOffset(minStoreLoadRefAddress)
				.setCreateComplexDataFromPointers(createComplexDataFromPointers);

		AddressSet resultSet = symEval.flowConstants(flowStart, flowSet, eval, true, monitor);

		return resultSet;
	}

	/* @Override */
	public void optionsChanged(Options options, Program program) {
		base.optionsChanged(options, program);
	}


	internal class _Anon_ConstantPropagationContextEvaluator_1 : ConstantPropagationContextEvaluator
	{
		public _Anon_ConstantPropagationContextEvaluator_1() : @base(monitor, trustWriteMemOption) {}


				/**
				 * Check if there are any data references to this location.
				 * @param program
				 * @param addr
				 * @return true if there are any data references to addr
				 */
				private bool hasDataReferenceTo(Program program, Address addr) {
					ReferenceManager refMgr = program.getReferenceManager();
					if (!refMgr.hasReferencesTo(addr)) {
						return false;
					}
					ReferenceIterator referencesTo = refMgr.getReferencesTo(addr);
					while (referencesTo.hasNext()) {
						Reference reference = referencesTo.next();
						if (reference.getReferenceType().isData()) {
							return true;
						}
					}
					return false;
				}

				private bool isLinkRegister(VarnodeContext context, Varnode pcVal) {
					return (pcVal.isRegister() &&
						pcVal.getAddress().equals(linkRegister.getAddress())) ||
						(context.isSymbol(pcVal) && pcVal.getAddress()
								.getAddressSpace()
								.getName()
								.equals(linkRegister.getName()) &&
							pcVal.getOffset() == 0);
				}

				/* @Override */
				public bool evaluateDestination(VarnodeContext context, Instruction instruction) {
					return base.evaluateDestination(context, instruction);
				}

				/* @Override */
				public bool evaluateReturn(Varnode retVN, VarnodeContext context,
						Instruction instruction) {
					// check if a return is actually returning, or is branching with a constant PC

					// if flow already overridden, don't override again
					if (instruction.getFlowOverride() != FlowOverride.NONE) {
						return false;
					}

					if (retVN != null && context.isConstant(retVN)) {
						long offset = retVN.getOffset();
						if (offset > 3 && offset != -1) {
							FlowOverride flowOverride = FlowOverride.CALL_RETURN;
							// need to override the return flow to a branch
							instruction.setFlowOverride(flowOverride);
							
							// need to analyze this flow again with the new return tag
							AutoAnalysisManager aMgr= AutoAnalysisManager.getAnalysisManager(program);
							aMgr.codeDefined(flowStart);
						}
					}

					return false;
				}
			
	}

